                        <li>buttons[]: {buttonsPass ? '✓' : '✗'} {this.buttons.length} items, all $$Function? {this.buttons.every(b => b instanceof $Chemical && b.constructor.name === '$$Function') ? 'yes' : 'no'}</li>
