'use client'
import { $Chemical, List, $use, $check, Undefined } from '@/chemistry';
import React, { useState, useEffect } from 'react';

// ============================================
// TEST COMPONENTS
// ============================================

// Simple chemicals for testing
export class $Label extends $Chemical {
    $text = 'Label';
    $color?: string = '#333';
    
    view() {
        return <span style={{ color: this.$color }}>{this.$text}</span>;
    }
}

export class $Chapter extends $Chemical {
    $title = 'Chapter';
    $pageCount = 10;
    
    view() {
        return <div>{this.$title} ({this.$pageCount} pages)</div>;
    }
}

export class $Book extends $Chemical {
    $title = 'Book';
    chapters: $Chapter[] = [];
    
    $Book(...chapters: $Chapter[]) {
        $check(chapters, [$Chapter]);
        this.chapters = chapters;
    }
    
    view() {
        return <div>{this.$title} with {this.chapters.length} chapters</div>;
    }
}

// Simple functional component for testing
const SimpleCard: React.FC<{ title?: string }> = ({ title = 'Card' }) => {
    return <div style={{ padding: '10px', background: '#e0e0e0' }}>{title}</div>;
};

// ============================================
// COMPLEX VALIDATOR FOR TESTING
// ============================================

export class $ComplexValidator extends $Chemical {
    header!: $Label;
    count!: number;
    items: $Chapter[] = [];
    config?: Object;
    callback?: Function;
    matrix: number[][] = [];
    
    $ComplexValidator(
        header: $Label,
        count: number,
        items: $Chapter[],
        config: Object | undefined,
        callback: Function | undefined,
        matrix: number[][]
    ) {
        $check(header, $Label);
        $check(count, Number);
        $check(items, [$Chapter]);
        $check(config, Object, undefined);
        $check(callback, Function, undefined);
        $check(matrix, [[Number]]);
        
        this.header = header;
        this.count = count;
        this.items = items;
        this.config = config;
        this.callback = callback;
        this.matrix = matrix;
    }
    
    view() {
        return (
            <div style={{ padding: '10px', background: '#f0f0f0' }}>
                Valid ComplexValidator Instance
            </div>
        );
    }
}

// ============================================
// TEST RUNNER
// ============================================

interface TestCase {
    name: string;
    description: string;
    component: () => React.ReactElement;
}

class TestRunner {
    static runTest(testCase: TestCase): { passed: boolean; error?: string } {
        try {
            // Try to render the component
            const element = testCase.component();
            // If we get here without throwing, validation passed (shouldn't happen for error tests)
            return { passed: false, error: "Expected validation error but none was thrown" };
        } catch (e) {
            // We expect errors in these tests
            return { passed: true, error: (e as Error).message };
        }
    }
}

// ============================================
// TEST CASES
// ============================================

const Label = new $Label().Component;
const Chapter = new $Chapter().Component;
const Book = new $Book().Component;
const ComplexValidator = new $ComplexValidator().Component;

const validationTestCases: TestCase[] = [
    {
        name: "Wrong Chemical type",
        description: "Passing $Book where $Label expected",
        component: () => (
            <ComplexValidator>
                <Book />  {/* Wrong: should be Label */}
                <span>42</span>
                <List><Chapter /><Chapter /></List>
                <div>config</div>
                <SimpleCard />
                <List><List>1</List><List>2</List></List>
            </ComplexValidator>
        )
    },
    {
        name: "String instead of Number",
        description: "Passing string 'not a number' where number expected",
        component: () => (
            <ComplexValidator>
                <Label />
                <span>not a number</span>  {/* Wrong: should be number */}
                <List><Chapter /><Chapter /></List>
                <div>config</div>
                <Undefined />
                <List><List>1</List><List>2</List></List>
            </ComplexValidator>
        )
    },
    {
        name: "Mixed types in array",
        description: "Array contains $Label and $Book instead of all $Chapter",
        component: () => (
            <ComplexValidator>
                <Label />
                <span>42</span>
                <List>
                    <Chapter />
                    <Label />  {/* Wrong: should be Chapter */}
                    <Book />   {/* Wrong: should be Chapter */}
                </List>
                <Undefined />
                <Undefined />
                <List><List>1</List><List>2</List></List>
            </ComplexValidator>
        )
    },
    {
        name: "Non-object for Object parameter",
        description: "String passed where Object or undefined expected",
        component: () => (
            <ComplexValidator>
                <Label />
                <span>42</span>
                <List><Chapter /><Chapter /></List>
                <span>string not object</span>  {/* Wrong: should be object or undefined */}
                <Undefined />
                <List><List>1</List><List>2</List></List>
            </ComplexValidator>
        )
    },
    {
        name: "1D array instead of 2D",
        description: "Single-dimensional array where 2D array expected",
        component: () => (
            <ComplexValidator>
                <Label />
                <span>42</span>
                <List><Chapter /><Chapter /></List>
                <div>config</div>
                <Undefined />
                <List>1 2 3</List>  {/* Wrong: should be [[Number]] */}
            </ComplexValidator>
        )
    },
    {
        name: "Missing required parameter",
        description: "Matrix parameter (last required param) is missing",
        component: () => (
            <ComplexValidator>
                <Label />
                <span>42</span>
                <List><Chapter /><Chapter /></List>
                <Undefined />
                <Undefined />
                {/* Missing matrix parameter! */}
            </ComplexValidator>
        )
    },
    {
        name: "Extra parameters",
        description: "Too many arguments passed to constructor",
        component: () => (
            <ComplexValidator>
                <Label />
                <span>42</span>
                <List><Chapter /><Chapter /></List>
                <div>config</div>
                <SimpleCard />
                <List><List>1</List><List>2</List></List>
                <Label />  {/* Extra! */}
                <Book />   {/* Extra! */}
            </ComplexValidator>
        )
    },
    {
        name: "Null instead of undefined",
        description: "Null passed for optional parameter that accepts undefined",
        component: () => (
            <ComplexValidator>
                <Label />
                <span>42</span>
                <List><Chapter /><Chapter /></List>
                <span>null</span>  {/* Chemistry might interpret this differently */}
                <Undefined />
                <List><List>1</List><List>2</List></List>
            </ComplexValidator>
        )
    },
    {
        name: "Wrong function component",
        description: "Different function component than expected type",
        component: () => (
            <ComplexValidator>
                <Label />
                <span>42</span>
                <List><Chapter /><Chapter /></List>
                <div>config</div>
                <Label />  {/* Wrong: should be function component or undefined */}
                <List><List>1</List><List>2</List></List>
            </ComplexValidator>
        )
    },
    {
        name: "Empty array where non-empty expected",
        description: "Empty array for items parameter",
        component: () => (
            <ComplexValidator>
                <Label />
                <span>42</span>
                <List>{/* Empty! */}</List>
                <div>config</div>
                <Undefined />
                <List><List>1</List><List>2</List></List>
            </ComplexValidator>
        )
    }
];

